NoteVisual intuition about the eigenvalue equation





In plot the plot above you can visualy confirm that the Equation 3.1 is satisfied for any \(X_n(x)\): when the eigenvalue \(\lambda_x\) is greater than 1, the curve for the double derivative \(\frac{d^2X_n}{dx^2}\) is just a scaled-up version of the curve for \(X_n(x)\) multiplied by \(-1\). On the other hand, when the eigenvalue \(\lambda_x\) is between 0 and 1, the curve for \(\frac{d^2X_n}{dx^2}\) is a scaled-down version of the curve for \(X_n(x)\) multiplied by \(-1\). In the graph above, you can also confirm that the zero-flux boundary conditions are satisfied for \(X_n(x)\) at \(x=0\) and \(x=L_x\) since the slope of the curve is zero at these points.

2.5 Plotting the solution
Let’s plot the steady-state solution for randomly placed point-like sources in a 2D domain.


Code
Plotly = require("plotly.js-dist@2")

// Domain and parameters
Lx = 10
Ly = 10
D = 1
beta = 0.1
TruncationNmax = 30
TruncationMmax = 30

// Controls
viewof N = Inputs.range([1, 10], {
  value: 5,
  step: 1,
  label: "Number of sources N"
})

// Grid resolution for plotting
Nx = 80
Ny = 80

// Random sources (recomputed when N changes)
producers = {
  const arr = []
  for (let k = 0; k &lt; N; k++) {
    const xk = Math.random() * Lx
    const yk = Math.random() * Ly
    arr.push([xk, yk])
  }
  return arr
}

A = Array.from({length: N}, () =&gt; 1.0)

// Helper: epsilon_n
function epsilon(n) {
  return n === 0 ? 0.5 : 1.0
}

// Helper: eigenfunction phi_{n,m}(x,y)
function phi(n, m, x, y) {
  return Math.cos(n * Math.PI * x / Lx) * Math.cos(m * Math.PI * y / Ly)
}

// Helper: eigenvalue lambda_{n,m}
function lambda(n, m) {
  return Math.pow(n * Math.PI / Lx, 2) + Math.pow(m * Math.PI / Ly, 2)
}

// Helper: k_{n,m} = D * lambda_{n,m} + beta
function k_nm(n, m) {
  return D * lambda(n, m) + beta
}

// Compute q_{n,m} for all modes
function compute_q_nm(n, m) {
  let sum = 0
  for (let i = 0; i &lt; N; i++) {
    const xi = producers[i][0]
    const yi = producers[i][1]
    sum += A[i] * phi(n, m, xi, yi)
  }
  return (4 * epsilon(n) * epsilon(m) / (Lx * Ly)) * sum
}

// Create spatial grid
xGrid = Array.from({length: Nx}, (_, i) =&gt; i * Lx / (Nx - 1))
yGrid = Array.from({length: Ny}, (_, j) =&gt; j * Ly / (Ny - 1))

// Compute steady-state solution v_ss(x,y)
vss = {
  const z = []

  for (let j = 0; j &lt; Ny; j++) {
    const row = []
    for (let i = 0; i &lt; Nx; i++) {
      const x = xGrid[i]
      const y = yGrid[j]

      let value = 0
      // Sum over modes
      for (let n = 0; n &lt;= TruncationNmax; n++) {
        for (let m = 0; m &lt;= TruncationMmax; m++) {
          const q_nm = compute_q_nm(n, m)
          const k = k_nm(n, m)
          const phi_nm = phi(n, m, x, y)
          value += (q_nm / k) * phi_nm
        }
      }
      row.push(value)
    }
    z.push(row)
  }

  return z
}

