function F(x,y){
  let sum = 0
  let dx = LxNew/(Nx_0-1)
  let dy = LyNew/(Ny_0-1)
  for (let i=0; i&lt;Nx_0; i++){
    for (let j=0; j&lt;Ny_0; j++){
      let x_i = xs_0[i]
      let y_i = ys_0[j]
      let dist = Math.sqrt((x - x_i)**2 + (y - y_i)**2)
      sum += Math.exp(-dist/lambdaNew)*dx*dy
    }
  }
  return sum
}

